#!/usr/bin/env node
/**
 * ⭐ T9 · THE ATS REPORT, BUILT ONCE — the two generated files the one component needs.
 *
 *   client/src/themes/* (the theme registry)  ->  shared/atsReportTokens.js   the pair's token VALUES for all four
 *   client/src/index.css (--font-*)                                            themes, and the font stacks — read by
 *                                                                              shared/atsReportStyles.js onto :host
 *
 *   shared/atsBands.js · profileSignals.js ·  ->  extension/atsReport.js       ONE classic script (no import, no
 *   atsReportTokens.js · atsReportModel.js ·                                   export) carrying the SAME modules, for
 *   atsReportStyles.js · atsReportElement.js                                   the extension: its popup loads it with
 *                                                                              <script src>, its on-page panel injects
 *                                                                              it with executeScript({ files }), its
 *                                                                              service worker imports it for its side
 *                                                                              effect. Sets globalThis.__draftAtsReport.
 *
 * Why a bundle and not the modules themselves: the extension cannot reach ../shared at run time, executeScript's
 * `files` are classic scripts (an `import` there is a syntax error), and the extension ships no remote code (its CSP
 * is script-src 'self'). The bundler below is deliberately tiny and STRICT — it understands exactly the import and
 * export forms these six files use and throws on anything else, so it can never silently mis-bundle. Its output is
 * a function of the sources alone (LF, sorted, no timestamps), so the committed file can be checked byte for byte:
 * test/t9AtsReportComponent.test.js and scripts/buildExtension.mjs (through buildExtensionTokens' stale check) both
 * refuse a stale one.
 *
 *   node scripts/buildAtsReport.mjs           write shared/atsReportTokens.js and extension/atsReport.js
 *   node scripts/buildAtsReport.mjs --check   exit 1 if either is stale; write nothing
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const lf = (s) => s.replace(/\r\n/g, "\n");

const HEADER = (what) =>
  `/* GENERATED by scripts/buildAtsReport.mjs from ${what} — do not edit.\n` +
  `   Change the source and run: node scripts/buildAtsReport.mjs\n` +
  `   test/t9AtsReportComponent.test.js fails if this file and its sources disagree. */\n`;

/** The tokens the report's shadow root reads: the pair's, and "not enough signal"'s two. */
export const REPORT_TOKEN = (name) => name.startsWith("PAIR_") || name === "BAND_UNKNOWN" || name === "BAND_UNKNOWN_EDGE";
export const FONT_VARS = ["--font-display", "--font-body", "--font-count"];

/** shared/atsReportTokens.js, as a string (LF). */
export async function renderAtsReportTokens() {
  const { THEME_LIST } = await import(pathToFileURL(path.join(ROOT, "client/src/themes/index.js")).href);
  const indexCss = lf(fs.readFileSync(path.join(ROOT, "client/src/index.css"), "utf8"));
  const fonts = {};
  for (const v of FONT_VARS) {
    const m = new RegExp(`^\\s*${v}:\\s*([^;]+);`, "m").exec(indexCss);
    if (!m) throw new Error(`client/src/index.css declares no ${v}`);
    fonts[v] = m[1].trim();
  }
  const light = THEME_LIST.find((t) => t.id === "paper-light"), dark = THEME_LIST.find((t) => t.id === "charcoal-dark");
  if (!light || !dark) throw new Error("the registry lost Paper Light or Charcoal Dark — the OS-following default");
  const names = Object.keys(light.tokens).filter(REPORT_TOKEN);
  const themes = THEME_LIST.map((t) => {
    const missing = names.filter((n) => !(n in t.tokens));
    if (missing.length) throw new Error(`${t.id} lacks ${missing.join(", ")}`);
    const body = names.map((n) => `      ${n}: ${JSON.stringify(t.tokens[n])},`).join("\n");
    return `  ${JSON.stringify(t.id)}: Object.freeze({ scheme: ${JSON.stringify(t.scheme)}, contrast: ${JSON.stringify(t.contrast)}, tokens: Object.freeze({\n${body}\n  }) }),`;
  });
  return HEADER("client/src/themes/* (the registry) and client/src/index.css (--font-*)") +
    `// The ATS report's token VALUES, per theme — the one component (shared/atsReportElement.js) sets them on its own\n` +
    `// :host, so the card is the same pixels for the same theme in the web app, the popup and the on-page panel.\n` +
    `export const ATS_REPORT_THEMES = Object.freeze({\n${themes.join("\n")}\n});\n\n` +
    `/** No theme named: follow the OS, as the site's "system" preference does. */\n` +
    `export const ATS_REPORT_DEFAULT_THEMES = Object.freeze({ light: ${JSON.stringify(light.id)}, dark: ${JSON.stringify(dark.id)} });\n\n` +
    `export const ATS_REPORT_FONTS = Object.freeze({\n${FONT_VARS.map((v) => `  ${JSON.stringify(v)}: ${JSON.stringify(fonts[v])},`).join("\n")}\n});\n`;
}

// ── the strict mini-bundler ──────────────────────────────────────────────────────────────────────────────────────
/** The modules, in dependency order. Each may import only modules before it. */
export const BUNDLE_MODULES = ["atsBands.js", "profileSignals.js", "atsReportTokens.js", "atsReportModel.js", "atsReportStyles.js", "atsReportElement.js"];

/** One module's source → a function body returning its exports. Throws on any form it does not understand. */
export function transformModule(name, source, known) {
  let src = lf(source);
  const exportsOf = [];
  // import { a, b as c } from "./x.js";   (possibly over several lines)
  src = src.replace(/^import\s*\{([^}]*)\}\s*from\s*["']\.\/([\w.-]+)["'];?[ \t]*$/gm, (_, list, dep) => {
    if (!known.has(dep)) throw new Error(`${name} imports ${dep}, which is not bundled before it`);
    const binds = list.split(",").map((s) => s.trim()).filter(Boolean).map((s) => {
      const m = /^(\w+)(?:\s+as\s+(\w+))?$/.exec(s);
      if (!m) throw new Error(`${name}: an import the bundler does not understand: ${s}`);
      return m[2] ? `${m[1]}: ${m[2]}` : m[1];
    });
    return `const { ${binds.join(", ")} } = __m[${JSON.stringify(dep)}];`;
  });
  src = src.replace(/^export\s+(const|let|function|async function|class)\s+(\w+)/gm, (_, kind, id) => { exportsOf.push(id); return `${kind} ${id}`; });
  const rest = src.split("\n").filter((l) => /^\s*(import|export)\b/.test(l));
  if (rest.length) throw new Error(`${name}: an import/export the bundler does not understand: ${rest[0].trim()}`);
  return { body: src, exports: exportsOf };
}

/** extension/atsReport.js, as a string (LF). `tokensSource` lets a fresh token file be bundled before it is written. */
export async function renderAtsReportBundle({ tokensSource = null } = {}) {
  const known = new Set();
  const parts = [];
  for (const name of BUNDLE_MODULES) {
    const source = name === "atsReportTokens.js" && tokensSource != null ? tokensSource : fs.readFileSync(path.join(ROOT, "shared", name), "utf8");
    const { body, exports } = transformModule(name, source, known);
    known.add(name);
    parts.push(`// ── shared/${name} ${"─".repeat(Math.max(4, 100 - name.length))}\n` +
      `__m[${JSON.stringify(name)}] = (() => {\n${body.trimEnd()}\nreturn { ${exports.join(", ")} };\n})();\n`);
  }
  return HEADER(`shared/${BUNDLE_MODULES.join(", shared/")}`) +
    `// ⭐ T9 · THE ATS REPORT for the extension — the web app's one component, the same code. No import, no export:\n` +
    `// a classic script (popup <script src>, executeScript files) that is also a valid module (the service worker\n` +
    `// imports it for its side effect). It sets globalThis.__draftAtsReport and, where custom elements exist (the\n` +
    `// popup — NOT a content script's isolated world, where customElements is null), defines <draft-ats-report>.\n` +
    `(() => {\n"use strict";\nconst __m = {};\n${parts.join("\n")}\n` +
    `const api = Object.freeze({ ...__m["atsReportModel.js"], ...__m["atsReportElement.js"] });\n` +
    `globalThis.__draftAtsReport = api;\n` +
    `api.defineAtsReportElement();\n})();\n`;
}

/** Every generated path that is stale, repo-relative. Empty means up to date. */
export async function staleAtsReport() {
  const stale = [];
  const tokens = await renderAtsReportTokens();
  const have = (rel) => (fs.existsSync(path.join(ROOT, rel)) ? lf(fs.readFileSync(path.join(ROOT, rel), "utf8")) : null);
  if (have("shared/atsReportTokens.js") !== tokens) stale.push("shared/atsReportTokens.js");
  if (have("extension/atsReport.js") !== await renderAtsReportBundle({ tokensSource: tokens })) stale.push("extension/atsReport.js");
  return stale;
}

async function main() {
  if (process.argv.includes("--check")) {
    const stale = await staleAtsReport();
    if (stale.length) { console.error(`[atsReport] stale: ${stale.join(", ")}`); process.exit(1); }
    console.log("[atsReport] up to date");
    return;
  }
  const tokens = await renderAtsReportTokens();
  fs.writeFileSync(path.join(ROOT, "shared/atsReportTokens.js"), tokens);
  fs.writeFileSync(path.join(ROOT, "extension/atsReport.js"), await renderAtsReportBundle({ tokensSource: tokens }));
  console.log("[atsReport] wrote shared/atsReportTokens.js and extension/atsReport.js");
}

if (import.meta.url === pathToFileURL(process.argv[1] || "").href) await main();
